CREATE TRIGGER devices_postgres_values_insert BEFORE INSERT ON devices BEGIN SELECT CASE WHEN length(NEW."device_id")>128 OR length(NEW."app_version")>64 OR instr(NEW."device_id",char(0))>0 OR instr(NEW."first_seen_at",char(0))>0 OR instr(NEW."last_seen_at",char(0))>0 OR instr(NEW."app_version",char(0))>0 THEN RAISE(ABORT,'postgres value guard') END; END;
