CREATE TRIGGER health_metrics_postgres_values_insert BEFORE INSERT ON health_metrics BEGIN SELECT CASE WHEN length(NEW."workspace_id")>64 OR length(NEW."device_id")>128 OR length(NEW."id")>256 OR length(NEW."type")>128 OR length(NEW."unit")>64 OR length(NEW."source_name")>256 OR length(NEW."source_bundle_id")>256 OR length(NEW."export_id")>36 OR instr(NEW."workspace_id",char(0))>0 OR instr(NEW."device_id",char(0))>0 OR instr(NEW."id",char(0))>0 OR instr(NEW."type",char(0))>0 OR instr(NEW."unit",char(0))>0 OR instr(NEW."start_at",char(0))>0 OR instr(NEW."end_at",char(0))>0 OR instr(NEW."source_name",char(0))>0 OR instr(NEW."source_bundle_id",char(0))>0 OR instr(NEW."metadata",char(0))>0 OR instr(NEW."export_id",char(0))>0 THEN RAISE(ABORT,'postgres value guard') END; SELECT CASE WHEN NOT json_valid(NEW.metadata) THEN RAISE(ABORT,'postgres value guard') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM json_tree(NEW.metadata) WHERE instr(key,char(0))>0 OR (type='text' AND instr(atom,char(0))>0)) THEN RAISE(ABORT,'postgres value guard') END; END;
